// dsh-skill-manager-ytxue core: DSH skill 规范检查 / 自动修复 / 池管理（纯 Node，无 harness 依赖，可独立测试）
// DSH skill 规范（dsh-skill-filesystem）：
//   - 条目形态：<root>/<name>/SKILL.md（bundle）或 <root>/<name>.md（平铺），发现深度一层
//   - frontmatter：name 必填且 kebab-case（否则整条排除）；description 必填
//   - 可选字段：whenToUse / metadata / disable-model-invocation / user-invocable
//     （布尔字段必须 kebab 拼写且值为布尔，驼峰拼写或非布尔 → 整条排除）
//   - 目录名/文件名 = skill 身份，应与 name 一致
import { createHash } from "node:crypto";
import { existsSync } from "node:fs";
import { cp, mkdir, readdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { basename, dirname, extname, join } from "node:path";

export const KEBAB_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;

/**
 * 项目根判定（与 DSH skill-filesystem 一致）：从目录向上找含 .git 的最近祖先；无则返回目录自身。
 */
export function findProjectRoot(dir) {
  let d = dir;
  try {
    while (d) {
      if (existsSync(join(d, ".git"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  } catch {}
  return dir;
}

/** kebab-case 规整（与 DSH 官方 skill 命名规范一致）。 */
export function toKebab(s) {
  if (typeof s !== "string" || !s.trim()) return "";
  let out = s.replace(/([a-z0-9])([A-Z])/g, "$1-$2");
  out = out.replace(/[^a-zA-Z0-9]+/g, "-");
  out = out.toLowerCase();
  return out.replace(/^-+|-+$/g, "");
}

/** 宽松 frontmatter 解析：保留键序；返回 { fields: [{key, raw}], map, body }。 */
export function parseSkillDoc(text) {
  // Windows 工具（PS 5.1 Set-Content -Encoding UTF8 等）会在文件头写 UTF-8 BOM，
  // 不剥离会导致开头的 --- 失配、整个 frontmatter 解析失败。
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  const fields = [];
  let body = text;
  const m = /^---\r?\n/.exec(text);
  if (m) {
    const rest = text.slice(m[0].length);
    const end = rest.search(/\r?\n---(\r?\n|$)/);
    if (end !== -1) {
      const head = rest.slice(0, end);
      for (const raw of head.split(/\r?\n/)) {
        const line = raw.trim();
        if (!line || line.startsWith("#")) continue;
        const kv = line.match(/^([A-Za-z0-9-]+):\s*(.*)$/);
        if (!kv) continue;
        fields.push({ key: kv[1], raw: kv[2].trim() });
      }
      body = rest.slice(end).replace(/^\r?\n---\r?\n?/, "");
    }
  }
  const map = {};
  for (const f of fields) if (!(f.key in map)) map[f.key] = f.raw;
  return { fields, map, body };
}

/** 值规整：去引号。 */
export function unquote(v) {
  const s = String(v).trim();
  if (s.length >= 2 && ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'")))) return s.slice(1, -1);
  return s;
}

/** 序列化 frontmatter（保留原键序，fields 传入修改后的键值表）。 */
export function serializeSkillDoc(prev, nextMap, body) {
  const lines = [];
  for (const f of prev.fields) {
    if (!(f.key in nextMap)) continue;
    lines.push(`${f.key}: ${nextMap[f.key]}`);
    delete nextMap[f.key];
  }
  for (const [k, v] of Object.entries(nextMap)) lines.push(`${k}: ${v}`);
  return `---\n${lines.join("\n")}\n---\n${body}`;
}

/** 标量 YAML 转义：含特殊字符时用双引号包裹。 */
export function yamlScalar(v) {
  const s = String(v);
  if (/^[A-Za-z0-9 _\-\u4e00-\u9fff.()/%,:;!?@#&+=<>{}[\]]+$/.test(s) && !/^[-?:,\[\]{}#&*!|>'"%@`]/.test(s)) return s;
  return JSON.stringify(s);
}

const BOOL_KEYS = ["disable-model-invocation", "user-invocable"];
const BOOL_CAMEL = { disableModelInvocation: "disable-model-invocation", userInvocable: "user-invocable" };

/** 检查单个条目（root 下名为 name 的 bundle 或 flat）。返回 { name, kind, issues }。 */
export async function checkEntry(root, name) {
  const issues = [];
  const bundlePath = join(root, name, "SKILL.md");
  let docPath = bundlePath;
  let kind = "bundle";
  try {
    await stat(bundlePath);
  } catch {
    docPath = join(root, `${name}.md`);
    kind = "flat";
    try {
      await stat(docPath);
    } catch {
      return { name, kind: "none", issues: [{ code: "entry-missing", severity: "error", message: "条目不存在（无 SKILL.md 或无同名 .md）" }] };
    }
  }
  if (!KEBAB_RE.test(name)) {
    issues.push({ code: "dir-kebab", severity: "error", message: `目录/文件名非 kebab-case: ${name}` });
  }
  const text = await readFile(docPath, "utf8");
  const doc = parseSkillDoc(text);
  const fmName = doc.map.name !== undefined ? unquote(doc.map.name) : "";
  if (!fmName) {
    issues.push({ code: "name-missing", severity: "error", message: "frontmatter 缺少 name" });
  } else if (!KEBAB_RE.test(fmName)) {
    issues.push({ code: "name-kebab", severity: "error", message: `frontmatter name 非 kebab-case: ${fmName}` });
  }
  if (fmName && fmName !== name) {
    issues.push({ code: "name-mismatch", severity: "warning", message: `frontmatter name 与目录名不一致: ${fmName} != ${name}` });
  }
  if (doc.map.description === undefined || !unquote(doc.map.description)) {
    issues.push({ code: "desc-missing", severity: "error", message: "frontmatter 缺少 description（DSH 会排除）" });
  }
  for (const [camel, kebab] of Object.entries(BOOL_CAMEL)) {
    if (camel in doc.map) {
      issues.push({ code: "bool-camel", severity: "error", message: `布尔字段用驼峰拼写 ${camel}，应改为 ${kebab}（否则整条排除）` });
    }
  }
  for (const k of BOOL_KEYS) {
    if (k in doc.map) {
      const v = doc.map[k].trim().toLowerCase();
      if (v !== "true" && v !== "false") {
        issues.push({ code: "bool-type", severity: "error", message: `布尔字段 ${k} 的值非布尔: ${doc.map[k]}` });
      }
    }
  }
  return { name, kind, issues };
}

/** 修复一个条目；返回修复动作列表。以目录名为权威，能修则修，冲突/无法确定则记 issue 不动。 */
export async function fixEntry(root, name, log) {
  const fixed = [];
  const bundlePath = join(root, name, "SKILL.md");
  let docPath = bundlePath;
  let kind = "bundle";
  try {
    await stat(bundlePath);
  } catch {
    docPath = join(root, `${name}.md`);
    kind = "flat";
    try {
      await stat(docPath);
    } catch {
      return fixed;
    }
  }
  const text = await readFile(docPath, "utf8");
  const doc = parseSkillDoc(text);
  const next = {};
  for (const f of doc.fields) next[f.key] = f.raw;
  const fmName = doc.map.name !== undefined ? unquote(doc.map.name) : "";
  let canonicalName = name;

  // 1) 目录名非 kebab → 重命名目录（同时同步 name）
  if (!KEBAB_RE.test(name)) {
    const newName = toKebab(name);
    if (!newName) {
      return fixed; // 无法规整（纯中文等），跳过并保留 issues
    }
    const target = kind === "bundle" ? join(root, newName, "SKILL.md") : join(root, `${newName}.md`);
    let conflict = false;
    try {
      await stat(target);
      conflict = true;
    } catch {}
    if (conflict) {
      log("fix", `目录重命名冲突，跳过: ${name} -> ${newName}`);
      return fixed;
    }
    await rename(kind === "bundle" ? join(root, name) : join(root, `${name}.md`), kind === "bundle" ? join(root, newName) : join(root, `${newName}.md`));
    canonicalName = newName;
    docPath = kind === "bundle" ? join(root, newName, "SKILL.md") : join(root, `${newName}.md`);
    fixed.push({ code: "dir-kebab", detail: `目录重命名: ${name} -> ${newName}` });
    log("fix", `目录重命名: ${name} -> ${newName}`);
  }

  // 2) name 缺失 / 非 kebab / 与目录名不一致 → 以目录名为准
  if (!fmName || !KEBAB_RE.test(fmName) || fmName !== canonicalName) {
    next.name = yamlScalar(canonicalName);
    fixed.push({ code: "name-fix", detail: `frontmatter name 修正为: ${canonicalName}` });
    log("fix", `frontmatter name 修正: ${docPath} -> ${canonicalName}`);
  }

  // 3) description 缺失 → 补占位
  if (next.description === undefined || !unquote(next.description)) {
    next.description = yamlScalar(`${canonicalName} 技能说明（由 dsh-skill-manager-ytxue 自动补充，请按需编辑）。`);
    fixed.push({ code: "desc-fix", detail: `补充 description: ${canonicalName} 技能说明（占位，请编辑）` });
    log("fix", `补充 description: ${docPath}`);
  }

  // 4) 布尔字段：驼峰键 → kebab 键；非布尔值 → 修正/删除
  for (const [camel, kebab] of Object.entries(BOOL_CAMEL)) {
    if (camel in next) {
      next[kebab] = next[camel];
      delete next[camel];
      fixed.push({ code: "bool-camel", detail: `布尔字段 ${camel} -> ${kebab}` });
      log("fix", `布尔字段键修正: ${camel} -> ${kebab} (${docPath})`);
    }
  }
  for (const k of BOOL_KEYS) {
    if (k in next) {
      const v = next[k].trim().toLowerCase();
      if (v !== "true" && v !== "false") {
        if (v === "1" || v === "yes" || v === "on") { next[k] = "true"; }
        else if (v === "0" || v === "no" || v === "off" || v === "") { next[k] = "false"; }
        else {
          delete next[k];
          fixed.push({ code: "bool-type", detail: `布尔字段 ${k} 值无法识别，已删除: ${next[k] === undefined ? doc.map[k] : next[k]}` });
          log("fix", `布尔字段 ${k} 值无法识别，已删除 (${docPath})`);
          continue;
        }
        fixed.push({ code: "bool-type", detail: `布尔字段 ${k} 值修正为 ${next[k]}` });
        log("fix", `布尔字段 ${k} 值修正 (${docPath})`);
      }
    }
  }

  if (fixed.length) {
    await writeFile(docPath, serializeSkillDoc(doc, next, doc.body), "utf8");
  }
  return fixed;
}

/** 扫描根目录条目（bundle + flat），附带内容简介（frontmatter description）与文档路径。 */
export async function scanEntries(root) {
  const out = [];
  let entries = [];
  try {
    entries = await readdir(root, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    const p = join(root, e.name);
    if (e.isDirectory()) {
      try {
        const sk = join(p, "SKILL.md");
        await stat(sk);
        const doc = parseSkillDoc(await readFile(sk, "utf8"));
        out.push({
          name: e.name,
          kind: "bundle",
          path: p,
          docPath: sk,
          description: doc.map.description !== undefined ? unquote(doc.map.description) : "",
        });
      } catch {}
    } else if (e.isFile() && e.name.endsWith(".md") && e.name !== "SKILL.md") {
      const doc = parseSkillDoc(await readFile(p, "utf8"));
      out.push({
        name: e.name.slice(0, -3),
        kind: "flat",
        path: p,
        docPath: p,
        description: doc.map.description !== undefined ? unquote(doc.map.description) : "",
      });
    }
  }
  return out.sort((a, b) => a.name.localeCompare(b.name));
}

// ── 检查状态（红/绿点依据）：以 SKILL.md 内容指纹（sha1）判定"已检查"是否仍然有效 ──
export function checkStatePath(dshHome) {
  return join(dshHome, "skill-manager-ytxue.checked.json");
}

async function fileHash(p) {
  return createHash("sha1").update(await readFile(p)).digest("hex");
}

/** 读取检查状态表 { "<name>": { hash, ts } }；文件缺失/损坏时返回空表。 */
export async function loadCheckState(dshHome) {
  try {
    const j = JSON.parse(await readFile(checkStatePath(dshHome), "utf8"));
    if (j && typeof j === "object" && j.entries && typeof j.entries === "object") return j.entries;
  } catch {}
  return {};
}

/** 写回检查状态表（失败不阻塞主流程）。 */
export async function saveCheckState(dshHome, entries) {
  try {
    await writeFile(checkStatePath(dshHome), JSON.stringify({ version: 1, ts: new Date().toISOString(), entries }, null, 2), "utf8");
  } catch {}
}

/**
 * 审计并修复启用目录；返回 { checked, fixed, skipped }。
 * onlyUnchecked=true（默认）：内容指纹未变化且已入状态表的条目视为"已检查"并跳过；
 * 因此首次启用全量检查，之后只检查新增/被修改（红点）的 skill——满足"跳过已有 skill"。
 */
export async function auditSkills(dshHome, log, options = {}) {
  const { onlyUnchecked = true } = options;
  const skillsDir = join(dshHome, "skills");
  const entries = await scanEntries(skillsDir);
  const checkedState = await loadCheckState(dshHome);
  const checked = [];
  const fixed = [];
  const skipped = [];
  for (const e of entries) {
    let hash = "";
    try {
      hash = await fileHash(e.docPath);
    } catch {}
    if (onlyUnchecked && checkedState[e.name] && checkedState[e.name].hash === hash) {
      skipped.push(e.name);
      continue;
    }
    const result = await checkEntry(skillsDir, e.name);
    checked.push({ name: e.name, kind: e.kind, issues: result.issues });
    let finalName = e.name;
    if (result.issues.some((i) => i.severity === "error")) {
      const actions = await fixEntry(skillsDir, e.name, log);
      for (const a of actions) fixed.push({ name: e.name, ...a });
      // 目录被重命名时（dir-kebab），以新名为键登记检查状态，否则下次审计会重查
      const ren = actions.find((a) => a.code === "dir-kebab");
      if (ren) {
        const m = /->\s*([A-Za-z0-9-]+)\s*$/.exec(ren.detail);
        if (m) finalName = m[1];
      }
    }
    let newHash = hash;
    if (fixed.some((f) => f.name === e.name)) {
      // 条目可能被重命名/重写：按最终名重新解析文档路径，再算内容指纹
      const fresh = (await scanEntries(skillsDir)).find((x) => x.name === finalName);
      if (fresh) {
        try {
          newHash = await fileHash(fresh.docPath);
        } catch {}
      }
    }
    checkedState[finalName] = { hash: newHash, ts: new Date().toISOString() };
  }
  // 清理状态表中已不存在的条目（含重命名前的旧名键）
  const alive = new Set((await scanEntries(skillsDir)).map((x) => x.name));
  for (const k of Object.keys(checkedState)) {
    if (!alive.has(k)) delete checkedState[k];
  }
  await saveCheckState(dshHome, checkedState);
  log("audit", `审计完成: 检查 ${checked.length} 个，跳过 ${skipped.length} 个（已检查），修复 ${fixed.length} 处`);
  return { checked, fixed, skipped };
}

/** 解析池/启用目录中 name 对应的条目路径（bundle 或 flat 双形态）。 */
export async function resolveEntry(root, name) {
  try {
    await stat(join(root, name, "SKILL.md"));
    return { path: join(root, name), kind: "bundle" };
  } catch {}
  try {
    const p = join(root, `${name}.md`);
    await stat(p);
    return { path: p, kind: "flat" };
  } catch {}
  return null;
}

async function moveEntry(src, dst) {
  await mkdir(dirname(dst), { recursive: true });
  await rename(src, dst);
}

/** enable: pool -> skills（移动）。冲突报错。 */
export async function enableSkill(dshHome, name, log) {
  const pool = join(dshHome, "skill-pool");
  const skills = join(dshHome, "skills");
  if (!KEBAB_RE.test(name)) return { ok: false, error: `名称非 kebab-case: ${name}` };
  const src = await resolveEntry(pool, name);
  if (!src) return { ok: false, error: `池中未找到 skill: ${name}` };
  const conflict = await resolveEntry(skills, name);
  if (conflict) return { ok: false, error: `启用目录已存在同名条目: ${name}` };
  const target = src.kind === "bundle" ? join(skills, name) : join(skills, `${name}.md`);
  await mkdir(skills, { recursive: true });
  await moveEntry(src.path, target);
  log("enable", name);
  return { ok: true, name, from: "skill-pool", to: "skills" };
}

/** disable: skills -> pool（移动）。冲突报错。 */
export async function disableSkill(dshHome, name, log) {
  const pool = join(dshHome, "skill-pool");
  const skills = join(dshHome, "skills");
  if (!KEBAB_RE.test(name)) return { ok: false, error: `名称非 kebab-case: ${name}` };
  const src = await resolveEntry(skills, name);
  if (!src) return { ok: false, error: `启用目录中未找到 skill: ${name}` };
  const conflict = await resolveEntry(pool, name);
  if (conflict) return { ok: false, error: `池中已存在同名条目: ${name}（请手动处理冲突）` };
  const target = src.kind === "bundle" ? join(pool, name) : join(pool, `${name}.md`);
  await mkdir(pool, { recursive: true });
  await moveEntry(src.path, target);
  log("disable", name);
  return { ok: true, name, from: "skills", to: "skill-pool" };
}

/**
 * 分析导入来源：解析 kebab 名称、目标路径、是否已存在（不复制）。
 * 返回 { kebab, dest, flatten, isDir, skillFile, warnings, exists } 或 { error }。
 */
async function analyzeSource(destDir, source) {
  let st;
  try {
    st = await stat(source);
  } catch {
    return { error: `来源不存在: ${source}` };
  }
  const isDir = st.isDirectory();
  let skillFile = null;
  let flatten = false;
  if (isDir) {
    const sk = join(source, "SKILL.md");
    try {
      await stat(sk);
      skillFile = sk;
    } catch {
      const mds = (await readdir(source)).filter((f) => f.endsWith(".md"));
      if (mds.length === 1) { skillFile = join(source, mds[0]); flatten = true; }
      else if (mds.length === 0) return { error: `来源目录中没有 SKILL.md 或 .md 文件: ${source}` };
      else return { error: `来源目录有多个 .md 文件，无法确定主文件: ${source}` };
    }
  } else {
    if (extname(source).toLowerCase() !== ".md") return { error: `来源文件必须是 .md: ${source}` };
    skillFile = source;
    flatten = true;
  }
  const text = await readFile(skillFile, "utf8");
  const doc = parseSkillDoc(text);
  let rawName = doc.map.name !== undefined ? unquote(doc.map.name) : "";
  if (!rawName) {
    rawName = isDir && !flatten ? basename(source) : basename(source, extname(source));
  }
  const kebab = toKebab(rawName);
  if (!kebab) return { error: `无法从 '${rawName}' 生成 kebab-case 名称` };
  const dest = flatten ? join(destDir, `${kebab}.md`) : join(destDir, kebab);
  let exists = false;
  try {
    await stat(dest);
    exists = true;
  } catch {}
  return {
    kebab,
    dest,
    flatten,
    isDir,
    skillFile,
    exists,
    warnings: doc.map.description === undefined ? ["frontmatter 缺少 description，DSH 会排除无 description 的 skill，请补上后再启用"] : [],
  };
}

/**
 * 单条目导入（destDir 由调用方指定）。conflict: "skip"（默认，重名不覆盖）/ "overwrite"（删除目标后替换）。
 * 返回 { ok, name, path, warnings, overwritten } 或 { ok:false, error, conflict }。
 */
async function importOne(destDir, source, log, conflict) {
  const a = await analyzeSource(destDir, source);
  if (a.error) return { ok: false, error: a.error };
  let overwritten = false;
  try {
    if (a.exists) {
      if (conflict !== "overwrite") {
        return { ok: false, error: `目标目录已存在同名条目: ${a.kebab}（不覆盖）`, conflict: true };
      }
      await rm(a.dest, { recursive: true, force: true });
      overwritten = true;
    }
    if (a.isDir && !a.flatten) await cp(source, a.dest, { recursive: true });
    else await cp(a.skillFile, a.dest);
  } catch (e) {
    return { ok: false, error: `复制失败: ${String(e && e.message ? e.message : e)}（来源: ${source}）` };
  }
  log("import", `${source} -> ${a.dest}${overwritten ? " (overwrite)" : ""}`);
  return { ok: true, name: a.kebab, path: a.dest, warnings: a.warnings, overwritten };
}

/**
 * import: 外部 skill 复制到目标目录（默认池 skill-pool；target="skills" 时直接复制到启用目录 skills\，立即生效）。
 */
export async function importSkill(dshHome, source, log, options = {}) {
  const { target: targetName = "pool", conflict = "skip" } = options;
  const destDir = targetName === "skills" ? join(dshHome, "skills") : join(dshHome, "skill-pool");
  const r = await importOne(destDir, source, log, conflict);
  if (!r.ok) return r;
  return { ok: true, name: r.name, target: targetName, path: r.path, warnings: r.warnings, overwritten: !!r.overwritten };
}

/** 收集候选导入项（单条目或集合目录直接子级）。 */
async function collectCandidates(source) {
  let st;
  try {
    st = await stat(source);
  } catch {
    return { error: `来源不存在: ${source}` };
  }
  if (!st.isDirectory()) return { kind: "single", candidates: [source] };
  let isSingle = true;
  try {
    await stat(join(source, "SKILL.md"));
  } catch {
    isSingle = false;
  }
  if (isSingle) return { kind: "single", candidates: [source] };
  let children;
  try {
    children = await readdir(source, { withFileTypes: true });
  } catch {
    return { error: `无法读取目录: ${source}` };
  }
  const candidates = [];
  for (const c of children.sort((a, b) => a.name.localeCompare(b.name))) {
    const p = join(source, c.name);
    if (c.isDirectory()) {
      let isSkill = false;
      try {
        await stat(join(p, "SKILL.md"));
        isSkill = true;
      } catch {
        try {
          const mds = (await readdir(p)).filter((f) => f.endsWith(".md"));
          if (mds.length === 1) isSkill = true;
        } catch {}
      }
      if (isSkill) candidates.push(p);
    } else if (c.name.endsWith(".md") && c.name !== "SKILL.md") {
      candidates.push(p);
    }
  }
  if (candidates.length === 0) {
    return { error: `该目录下未找到任何 skill 条目（需含 SKILL.md 的子目录或 .md 文件）: ${source}` };
  }
  return { kind: "batch", candidates };
}

/**
 * 批量导入（两阶段：dryRun 预检 → 执行）。
 * - dryRun=true：只分析不复制，返回 { kind, pending, conflicts, failed }（pending 全部、conflicts 重名项）
 * - 执行：conflict="skip"（默认）→ 重名计入 skipped；conflict="overwrite" → 删除目标后替换（计入 imported，overwritten=true）
 * - 返回 { ok, data: { kind, imported, skipped, failed } }。
 */
export async function importPath(dshHome, source, log, options = {}) {
  const { target: targetName = "pool", conflict = "skip", dryRun = false } = options;
  const destDir = targetName === "skills" ? join(dshHome, "skills") : join(dshHome, "skill-pool");
  const col = await collectCandidates(source);
  if (col.error) return { ok: false, error: col.error };
  const kind = col.kind;
  const pending = [];
  const conflicts = [];
  const failed = [];
  for (const c of col.candidates) {
    const a = await analyzeSource(destDir, c);
    if (a.error) {
      failed.push({ source: c, error: a.error });
      continue;
    }
    pending.push({ name: a.kebab, source: c, warnings: a.warnings });
    if (a.exists) conflicts.push({ name: a.kebab, source: c });
  }
  if (dryRun) {
    return { ok: true, data: { kind, pending, conflicts, failed } };
  }
  const imported = [];
  const skipped = [];
  for (const c of col.candidates) {
    const r = await importOne(destDir, c, log, conflict);
    if (r.ok) imported.push({ name: r.name, source: c, warnings: r.warnings || [], overwritten: !!r.overwritten });
    else if (r.conflict) skipped.push({ name: r.name, source: c });
    else failed.push({ source: c, error: r.error });
  }
  return { ok: true, data: { kind, imported, skipped, failed } };
}

/** 枚举盘符（Windows A-Z 探测）；非 Windows 返回根 "/"。 */
export async function listDrives() {
  if (process.platform !== "win32") {
    return { ok: true, data: { path: "__drives__", entries: [{ name: "/", isDir: true }] } };
  }
  const entries = [];
  for (let c = 65; c <= 90; c++) {
    const letter = String.fromCharCode(c);
    try {
      const st = await stat(`${letter}:\\`);
      if (st.isDirectory()) entries.push({ name: `${letter}:`, isDir: true });
    } catch {}
  }
  return { ok: true, data: { path: "__drives__", entries } };
}

/** 盘符根规范化：Windows 上 "C:"（无斜杠）是"该盘当前目录"语义而非根目录
 * （nodejs/node#7215 等社区共识），任何裸盘符一律补成 "C:\"。 */
function normalizeDirPath(p) {
  const s = String(p || "").trim();
  if (/^[A-Za-z]:$/.test(s)) return s + "\\";
  if (/^[A-Za-z]:[\\/]$/.test(s)) return s;
  return s.replace(/[\\/]+$/, "") || "/";
}

/**
 * 列出目录内容（目录选择器用）。
 * - path 为空或 "__drives__" → 返回盘符列表（"此电脑"），从而可以选择任意磁盘；
 * - 否则列出该目录（盘符根保持 "C:\" 形态，普通路径容忍尾部斜杠）。
 * 条目类型用 readdir withFileTypes 的 dirent 判断（不逐个 stat，避免权限目录被静默跳过）；
 * 符号链接/junction 目录用 stat 兜底（失败视为目录）；任何条目都显示，不因 stat 失败而缺失。
 */
export async function listDir(path) {
  if (!path || path === "__drives__") return listDrives();
  const target = normalizeDirPath(path);
  let st;
  try {
    st = await stat(target);
  } catch {
    return { ok: false, error: `目录不存在或不可访问: ${target}` };
  }
  if (!st.isDirectory()) return { ok: false, error: `不是目录: ${target}` };
  let dirents = [];
  try {
    dirents = await readdir(target, { withFileTypes: true });
  } catch {
    return { ok: false, error: `无法读取目录: ${target}` };
  }
  const entries = [];
  // 并行解析符号链接/junction 类型（其余条目 dirent 直读），避免大目录逐个 stat 串行拖慢
  await Promise.all(
    dirents.sort((a, b) => a.name.localeCompare(b.name)).map(async (d) => {
      let isDir = d.isDirectory();
      if (!isDir && d.isSymbolicLink()) {
        try {
          isDir = (await stat(join(target, d.name))).isDirectory();
        } catch {
          // stat 失败（权限/断裂链接等）：视为目录允许尝试进入，避免条目"读不到"
          isDir = true;
        }
      }
      entries.push({ name: d.name, isDir });
    })
  );
  return { ok: true, data: { path: target, count: entries.length, entries } };
}

/**
 * 状态快照：每项附带内容简介 description 与检查状态 checked（红/绿点依据）。
 * - enabled：用户级 `~/.dsh/skills`（scope "user"，rank 400）
 * - pool：`~/.dsh/skill-pool`（零挂载）
 * - projects：项目级 skill——`currentRoot`（当前项目，来自最近创建的主会话 cwd，标 current:true）
 *   + projectRoots（显式配置补充）；每个项目扫描 `.dsh/skills`（rank 100）+ `.agents/skills`（rank 200），
 *   条目 scope "project"，只读展示，不参与规范检查（checked 恒 false）。
 *   默认只显示当前项目，不堆叠其他项目的 skill。
 */
export async function state(dshHome, options = {}) {
  const { projectRoots = [], currentRoot = "" } = options;
  const skills = await scanEntries(join(dshHome, "skills"));
  const pool = await scanEntries(join(dshHome, "skill-pool"));
  const checkedState = await loadCheckState(dshHome);
  const withStatus = async (items, scope, rank, projectRoot) => {
    const out = [];
    for (const it of items) {
      let hash = "";
      try {
        hash = await fileHash(it.docPath);
      } catch {}
      out.push({
        name: it.name,
        kind: it.kind,
        path: it.path,
        description: it.description || "",
        scope: it.scope !== undefined ? it.scope : scope,
        rank: it.rank !== undefined ? it.rank : rank,
        projectRoot: it.projectRoot !== undefined ? it.projectRoot : projectRoot || undefined,
        checked: scope === "project" || it.scope === "project" ? false : !!(checkedState[it.name] && checkedState[it.name].hash === hash),
      });
    }
    return out;
  };
  const roots = [];
  if (currentRoot) roots.push({ root: currentRoot, current: true });
  for (const r of projectRoots) {
    if (r && r !== currentRoot) roots.push({ root: r, current: false });
  }
  const projects = [];
  for (const { root, current } of roots) {
    const items = [];
    // 项目级两个扫描根：<项目根>/.dsh/skills（rank 100）与 <项目根>/.agents/skills（rank 200）
    for (const sub of [".dsh", ".agents"]) {
      const rank = sub === ".dsh" ? 100 : 200;
      const dir = join(root, sub, "skills");
      const found = await scanEntries(dir);
      for (const it of found) {
        items.push({ ...it, scope: "project", rank, projectRoot: root });
      }
    }
    projects.push({ root, current, items: await withStatus(items, "project", 0, root) });
  }
  return {
    dshHome,
    enabled: await withStatus(skills, "user", 400, ""),
    pool: await withStatus(pool, "user", 400, ""),
    projects,
  };
}
